SELECT data->>'user' AS "user", data->'actor'->>'alternateId' AS "actor.alternateId", data->>'CommandLine' AS cmd FROM security_events WHERE data->>'action' ILIKE 'transfer'
WITH combined_events AS (SELECT * FROM security_events WHERE data->>'action' ILIKE 'transfer') SELECT data->>'user' AS "user", SUM((CASE WHEN data->>'bytes' ~ '^[-+]?([0-9]{1,100}\.?[0-9]{0,100}|\.[0-9]{1,100})([eE][-+]?[0-9]{1,3})?$' THEN (data->>'bytes')::numeric END)) AS value_sum FROM combined_events GROUP BY data->>'user' HAVING SUM((CASE WHEN data->>'bytes' ~ '^[-+]?([0-9]{1,100}\.?[0-9]{0,100}|\.[0-9]{1,100})([eE][-+]?[0-9]{1,3})?$' THEN (data->>'bytes')::numeric END)) >= 1000000
